+        assumeFalse(
+            "Testing upgrades from before CompatibilityVersions held mapping versions in cluster state",
+            testFeatureService.clusterHasFeature(RestTestLegacyFeatures.SYSTEM_INDICES_MAPPING_VERSION_IN_CLUSTER_STATE.id())
