+
+    @Override
+    protected boolean isRCS2() {
+        return false;
+    }
+
+    @Before
+    @Override
+    public void setUp() throws Exception {
+        configureRemoteCluster(REMOTE_CLUSTER_ALIAS, fulfillingCluster, true, randomBoolean(), false);
+        super.setUp();
+    }
